solution.javascript:
function chantLutins(n) {
  const chant = [];
  for (let i = 1; i <= n; i++) {
    if (i % 15 === 0) {
      chant.push("JingleBells");
    } else if (i % 3 === 0) {
      chant.push("Jingle");
    } else if (i % 5 === 0) {
      chant.push("Bells");
    } else {
      chant.push(String(i));
    }
  }
  return chant;
}

