solution.javascript:
function chantAvance(n, regles) {
  const chant = [];
  let apresPouf = false;
  for (let i = 1; i <= n; i++) {
    let mot = "";
    if (apresPouf) {
      mot = "Chut";
    } else if (String(i).includes("7")) {
      mot = "Pouf";
    } else {
      for (const [diviseur, texte] of regles) {
        if (i % diviseur === 0) {
          mot += texte;
        }
      }
      if (mot === "") {
        mot = String(i);
      }
    }
    apresPouf = !apresPouf && mot === "Pouf" && String(i).includes("7");
    chant.push(mot);
  }
  return chant;
}

